using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
class TaskbarPresetUiTests {
 static int checks,failures;static object Get(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,args);}
 static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static T Find<T>(DependencyObject o,Func<T,bool> test)where T:DependencyObject{var item=o as T;if(item!=null&&test(item))return item;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++){var child=Find<T>(VisualTreeHelper.GetChild(o,i),test);if(child!=null)return child;}return null;}
 static T Named<T>(DependencyObject o,string name)where T:DependencyObject{return Find<T>(o,x=>System.Windows.Automation.AutomationProperties.GetName(x)==name);}
 static void Pump(int ms=100){var f=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();f.Continue=false;};timer.Start();Dispatcher.PushFrame(f);}
 static void Click(Window w,string text){var b=Find<Button>(w,x=>Convert.ToString(x.Content)==text);if(b==null)throw new Exception("Missing button "+text);b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
 static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(b));using(var stream=File.Create(path))encoder.Save(stream);}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{
 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;pet.Show();Pump(200);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.ShowPage("任务栏外观");Pump();Click(w,"预设管理 · 保存与恢复 ▾");Click(w,"柯南蓝");Click(w,"间距与留白");Named<Slider>(w,"列与列间隔（0–120）滑块").Value=42;Named<TextBox>(w,"新预设名称").Text="午后蓝";Click(w,"另存为新预设");Check(TaskbarPresets.Find(assistant.Config.Monitor,"午后蓝").Appearance.ItemGap==42,"native save as stores edited draft");Check(assistant.Config.Monitor.Appearance.ItemGap!=42,"saving preset does not apply runtime appearance");Named<Slider>(w,"列与列间隔（0–120）滑块").Value=7;Click(w,"重新载入预设");Check(((MonitorConfig)Get(w,"taskbarDraft")).Appearance.ItemGap==42,"reload saved preset undoes uncommitted edit");Click(w,"应用并保存任务栏外观");Check(assistant.Config.Monitor.Appearance.ItemGap==42,"apply commits preview separately");Click(w,"柯南蓝");Named<Slider>(w,"列与列间隔（0–120）滑块").Value=17;Click(w,"覆盖所选预设");Check(TaskbarPresets.Find(assistant.Config.Monitor,"柯南蓝").Appearance.ItemGap==17,"native overwrite stores built in customization");Click(w,"柯南蓝");Check(((MonitorConfig)Get(w,"taskbarDraft")).Appearance.ItemGap==17,"quick preset button loads saved override");Click(w,"恢复内置默认");Check(TaskbarPresets.Find(assistant.Config.Monitor,"柯南蓝")==null&&((MonitorConfig)Get(w,"taskbarDraft")).Appearance.ItemGap==TaskbarAppearance.Preset("柯南蓝").ItemGap,"native reset restores factory preset");Check(assistant.Config.Monitor.Appearance.ItemGap==42,"factory reset stays preview only");Click(w,"重新载入已保存设置");Check(((MonitorConfig)Get(w,"taskbarDraft")).Appearance.ItemGap==42,"revert restores applied appearance");var choice=Named<ComboBox>(w,"任务栏预设选择");int custom=-1;for(int i=0;i<choice.Items.Count;i++)if(Convert.ToString(choice.Items[i]).StartsWith("午后蓝"))custom=i;choice.SelectedIndex=custom;Pump();Check(((MonitorConfig)Get(w,"taskbarDraft")).Appearance.ItemGap==42,"custom selector loads saved appearance");Check(!Find<Button>(w,b=>Convert.ToString(b.Content)=="恢复内置默认").IsEnabled&&Find<Button>(w,b=>Convert.ToString(b.Content)=="删除自定义预设").IsEnabled,"reset and delete availability matches preset type");Shot(w,Path.Combine(args[0],"preset-manager-native.png"));Click(w,"字体与颜色");Named<TextBox>(w,"默认数值颜色").Text="#FFA36B";Click(w,"覆盖所选预设");var restored=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check(TaskbarPresets.Find(restored.Config.Monitor,"午后蓝").Appearance.ValueColor=="#FFA36B","custom overwrite color survives runtime restart");Check(restored.Config.Monitor.Appearance.ItemGap==42&&TaskbarPresets.Find(restored.Config.Monitor,"柯南蓝")==null,"applied settings and reset persist independently");restored.Telemetry.Dispose();Shot(w,Path.Combine(args[0],"preset-colors-native.png"));
 }catch(Exception e){failures++;Console.WriteLine(e);}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"preset-ui-results.json"),"{\"checks\":"+checks+",\"failures\":"+failures+"}");return failures==0?0:1;}
}
